<?php defined('BASEPATH') or exit('No direct script access allowed');
$company_page_title='Compras da empresa'; require APPPATH.'views/admin/companies/layout_head.php';
$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); $money=static fn($v)=>CompanyPurchasesValues::display((int)$v);
$url=fn(string $query='')=>CompanyRequestScope::adminUrl($this,'company_purchases'.$query);
$form=function (string $action,$object=null,$revision=null,$request=null,bool $multipart=false) use ($url,$e,$tab,$company_purchases_csrf): void {
    $actionUrl=$url('?tab='.$tab.($request===null?'':'&request='.(int)$request)); $attrs=['id'=>'purchase-'.$action.($object===null?'':'-'.$object)];
    echo $multipart?form_open_multipart($actionUrl,$attrs):form_open($actionUrl,$attrs);
    $fields=['action'=>$action,'company_purchases_csrf'=>$company_purchases_csrf,'request_key'=>bin2hex(random_bytes(32))];
    if ($object!==null) { $fields['object_id']=$object; } if ($revision!==null) { $fields['revision']=$revision; } if ($request!==null) { $fields['request_id']=$request; }
    foreach ($fields as $name=>$value) { ?><input type="hidden" name="<?= $e($name) ?>" value="<?= $e($value) ?>"><?php }
};
$states=['open'=>'Aberta','approved'=>'Aprovada','ordered'=>'Pedido emitido','part_received'=>'Recebido parcialmente','received'=>'Recebido','cancelled'=>'Cancelado'];
?><style>.purchase-tabs{display:flex;gap:12px;flex-wrap:wrap;margin:20px 0}.purchase-tabs a{padding:8px;border-bottom:2px solid #dbe3ed}.purchase-tabs [aria-current]{border-color:#24679b;font-weight:700}.purchase-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}.purchase-grid label{display:block}.purchase-grid input,.purchase-grid select{width:100%;box-sizing:border-box}.purchase-form{padding:16px 0;border-bottom:1px solid #dbe3ed}.purchase-table{width:100%;border-collapse:collapse;min-width:580px}.purchase-table th,.purchase-table td{padding:10px;text-align:left;border-bottom:1px solid #ddd}.purchase-table input{max-width:140px}.purchase-table form{margin:0}.purchase-note{padding:14px;background:#edf4fb;border-left:4px solid #2b6494}.purchase-warning{padding:14px;background:#fff5e5;border-left:4px solid #b47113}.purchase-link{width:100%;font-family:monospace}.purchase-section{margin:24px 0;padding-top:14px;border-top:1px solid #dbe3ed}.purchase-inline{display:inline-block;margin-right:8px}input,select,textarea{max-width:100%}details{margin:18px 0}summary{cursor:pointer;font-weight:600}</style>
<style>.purchase-card{overflow-wrap:anywhere}</style>
<section class="company-settings-card purchase-card"><h1>Compras da empresa</h1><p>Fornecedores, requisições, cotações, pedidos e recebimentos da empresa ativa. Documentos fechados preservam a origem e registram uma despesa e um título a pagar.</p>
<nav class="purchase-tabs" aria-label="Etapas de compras"><?php foreach (['requests'=>'Requisições','suppliers'=>'Fornecedores','orders'=>'Pedidos','payables'=>'Contas a pagar','report'=>'Relatório','settings'=>'Configuração'] as $t=>$label) { if (($t==='report'&&!$capabilities['report'])||($t==='settings'&&!$capabilities['settings'])) { continue; } ?><a href="<?= $e($url('?tab='.$t)) ?>" <?= $tab===$t?'aria-current="page"':'' ?>><?= $e($label) ?></a><?php } ?></nav>
<?php if ($error) { ?><p role="alert" class="alert alert-danger"><?= $e($error) ?></p><p><a href="<?= $e($url('?tab='.$tab)) ?>">Reabrir compras</a></p><?php } ?>
<?php if (!$settings&&$tab!=='settings') { ?><p class="purchase-warning">Antes de criar uma requisição, configure a numeração e as taxas de câmbio explícitas desta empresa. <a href="<?= $e($url('?tab=settings')) ?>">Abrir configuração</a></p><?php } ?>
<?php if ($tab==='settings'&&$capabilities['settings']) { ?><h2>Numeração e câmbio</h2><p>A numeração cresce separadamente por empresa e tipo de documento, sem reinício mensal. O prefixo afeta somente novos documentos. O câmbio informado é capturado no pedido; não é consultado em um provedor nem usado como confirmação do valor pago no banco.</p>
<?php $form('configure',null,$settings['revision']??null); $rates=$settings['rates']??['BRL'=>1000000]; ?><div class="purchase-grid"><label>Prefixo (letras maiúsculas, números e sublinhado)<input class="form-control" name="purchase[prefix]" value="<?= $e($settings['prefix']??'COMPRA') ?>" pattern="[A-Z0-9_]{1,12}" maxlength="12" required></label><label>Moeda base<select class="form-control" name="purchase[base_currency]"><?php foreach (['BRL','USD','EUR'] as $currency) { ?><option <?= ($settings['base_currency']??'BRL')===$currency?'selected':'' ?>><?= $currency ?></option><?php } ?></select></label></div><p>Valor de uma unidade da moeda em unidades da moeda base. Para a moeda base, informe 1.000000. Deixe moedas ainda não configuradas em branco.</p><div class="purchase-grid"><?php foreach (['BRL','USD','EUR'] as $currency) { ?><label><?= $currency ?><input class="form-control" name="purchase[rates][<?= $currency ?>]" inputmode="decimal" value="<?= isset($rates[$currency])?$e(CompanyPurchasesValues::display($rates[$currency],6)):'' ?>"></label><?php } ?></div><button type="submit">Salvar configuração</button></form><?php } ?>
<?php if ($tab==='suppliers') { ?><h2>Fornecedores</h2><div class="table-responsive"><table class="purchase-table"><thead><tr><th>Código</th><th>Nome</th><th>Identificação</th><th>E-mail</th><th>Estado</th></tr></thead><tbody><?php foreach ($page['items'] as $r) { ?><tr><td><?= (int)$r['id'] ?></td><td><a href="<?= $e($url('?tab=suppliers&supplier='.(int)$r['id'])) ?>"><?= $e($r['name']) ?></a></td><td><?= $e($r['tax_id']) ?></td><td><?= $e($r['email']) ?></td><td><?= (int)$r['active']?'Ativo':'Inativo' ?></td></tr><?php } ?></tbody></table></div>
<?php if (($editSupplier&&$capabilities['edit'])||(!$editSupplier&&$capabilities['create'])) { ?><h2><?= $editSupplier?'Editar fornecedor':'Cadastrar fornecedor' ?></h2><p>Alterações cadastrais valem para operações futuras. Pedidos já emitidos conservam a identidade e os preços capturados.</p><?php $form('supplier',$editSupplier['id']??null,$editSupplier['revision']??null); ?><div class="purchase-grid"><?php foreach (['name'=>['Nome',191],'tax_id'=>['CPF, CNPJ ou identificação tributária',32],'email'=>['E-mail',100],'phone'=>['Telefone',64]] as $field=>[$label,$length]) { ?><label><?= $label ?><input class="form-control" name="purchase[<?= $field ?>]" maxlength="<?= $length ?>" value="<?= $e($editSupplier[$field]??'') ?>" <?= $field==='name'?'required':'' ?> <?= $field==='email'?'type="email"':'' ?>></label><?php } ?></div><label>Endereço<textarea class="form-control" name="purchase[address]" maxlength="1000"><?= $e($editSupplier['address']??'') ?></textarea></label><label>Estado<select class="form-control" name="purchase[active]"><option value="1">Ativo</option><option value="0" <?= isset($editSupplier['active'])&&(int)$editSupplier['active']===0?'selected':'' ?>>Inativo</option></select></label><button>Salvar fornecedor</button></form><?php } ?>
<?php } elseif ($tab==='requests'&&!$workspace) { ?><h2>Requisições</h2><div class="table-responsive"><table class="purchase-table"><thead><tr><th>Referência</th><th>Necessidade</th><th>Data</th><th>Estado</th></tr></thead><tbody><?php foreach ($page['items'] as $r) { ?><tr><td><a href="<?= $e($url('?tab=requests&request='.(int)$r['id'])) ?>"><?= $e($r['reference']) ?></a></td><td><?= $e($r['title']) ?></td><td><?= $e($r['needed_date']) ?></td><td><?= $e($states[$r['state']]??$r['state']) ?></td></tr><?php } ?></tbody></table></div>
<?php if ($capabilities['create']&&$settings) { ?><h2>Nova requisição</h2><?php $form('request'); ?><div class="purchase-grid"><label>Descrição da necessidade<input class="form-control" name="purchase[title]" maxlength="191" required></label><label>Data necessária<input class="form-control" type="date" name="purchase[needed_date]" value="<?= gmdate('Y-m-d') ?>" required></label><label>Moeda<select class="form-control" name="purchase[currency]"><?php foreach (['BRL','USD','EUR'] as $currency) { ?><option><?= $currency ?></option><?php } ?></select></label></div><div class="table-responsive"><table class="purchase-table"><thead><tr><th>Item</th><th>Unidade</th><th>Quantidade (até 3 decimais)</th><th></th></tr></thead><tbody id="purchase-lines"><tr><td><input class="form-control" name="purchase[lines][0][description]" maxlength="191" required></td><td><input class="form-control" name="purchase[lines][0][unit]" maxlength="16" value="UN" required></td><td><input class="form-control" name="purchase[lines][0][quantity]" inputmode="decimal" value="1.000" required></td><td><button type="button" class="purchase-remove-line">Remover</button></td></tr></tbody></table></div><p><button id="purchase-add-line" type="button">Adicionar item</button></p><button>Criar requisição</button></form><?php } ?>
<?php } elseif ($tab==='orders') { ?><h2>Pedidos emitidos</h2><div class="table-responsive"><table class="purchase-table"><thead><tr><th>Pedido</th><th>Emissão</th><th>Entrega prevista</th><th>Total estimado</th><th>Recebimento</th></tr></thead><tbody><?php foreach ($page['items'] as $r) { ?><tr><td><a href="<?= $e($url('?tab=requests&request='.(int)$r['request_id'])) ?>"><?= $e($r['reference']) ?></a></td><td><?= $e($r['order_date']) ?></td><td><?= $e($r['expected_date']) ?></td><td><?= $e($r['currency'].' '.$money($r['total_cents'])) ?></td><td><?= $e($states[$r['state']]??$r['state']) ?></td></tr><?php } ?></tbody></table></div>
<?php } elseif ($tab==='payables') { ?><h2>Contas a pagar</h2><p class="purchase-note">Cada título corresponde a um documento e a uma única despesa canônica. A quitação externa manual e sua reversão alteram somente esta obrigação; não disparam ordem bancária, devolução de fundos ou baixa de contas a receber.</p><?php foreach ($page['items'] as $payable) { require APPPATH.'views/admin/companies/purchases_payable.php'; } ?>
<?php } elseif ($tab==='report'&&$report) { ?><h2>Posição de contas a pagar</h2><p>Fonte: títulos de documentos de compra e eventos imutáveis de quitação externa declarada. O relatório financeiro de despesas já reconhece o custo uma vez. As moedas permanecem separadas; não há conversão ou confirmação bancária implícita.</p><form method="get" action="<?= $e($url()) ?>"><input type="hidden" name="tab" value="report"><div class="purchase-grid"><label>Documentos desde<input class="form-control" type="date" name="from" value="<?= $e($report['from']) ?>" required></label><label>Posição em<input class="form-control" type="date" name="as_of" value="<?= $e($report['as_of']) ?>" required></label></div><button>Consultar</button></form><p><a href="<?= $e($url('?tab=report&from='.$report['from'].'&as_of='.$report['as_of'].'&format=csv')) ?>">Exportar período completo em CSV (até 5.000 títulos)</a></p><div class="table-responsive"><table class="purchase-table"><thead><tr><th>Fornecedor / documento</th><th>Vencimento</th><th>Moeda</th><th>Valor</th><th>Quitação declarada</th><th>Em aberto</th><th>Vencido</th></tr></thead><tbody><?php foreach ($report['items'] as $r) { ?><tr><td><?= $e($r['supplier'].' / '.$r['vendor_number']) ?></td><td><?= $e($r['due_date']) ?></td><td><?= $e($r['currency']) ?></td><td><?= $money($r['amount_cents']) ?></td><td><?= $money($r['declared_paid_cents']) ?></td><td><?= $money($r['outstanding_cents']) ?></td><td><?= $money($r['overdue_cents']) ?></td></tr><?php } ?></tbody><tfoot><?php foreach ($report['totals_for_this_page'] as $currency=>$total) { ?><tr><th colspan="2">Subtotal desta página</th><td><?= $e($currency) ?></td><td><?= $money($total['amount_cents']) ?></td><td><?= $money($total['declared_paid_cents']) ?></td><td><?= $money($total['outstanding_cents']) ?></td><td><?= $money($total['overdue_cents']) ?></td></tr><?php } ?></tfoot></table></div><?php if ($report['next']!==null) { ?><p><a href="<?= $e($url('?tab=report&from='.$report['from'].'&as_of='.$report['as_of'].'&after='.$report['next'])) ?>">Próxima página do relatório</a></p><?php } ?><?php } ?>
<?php if ($page['next']!==null&&!$workspace) { ?><p><a href="<?= $e($url('?tab='.$tab.'&after='.$page['next'])) ?>">Próxima página</a></p><?php } ?>
<?php if ($workspace) { require APPPATH.'views/admin/companies/purchases_workspace.php'; } ?>
</section><script>(()=>{const rows=document.getElementById('purchase-lines'),add=document.getElementById('purchase-add-line');if(!rows||!add)return;function names(){[...rows.rows].forEach((row,i)=>{row.querySelectorAll('input').forEach(input=>input.name=input.name.replace(/\[lines\]\[\d+\]/,'[lines]['+i+']'));});}add.addEventListener('click',()=>{if(rows.rows.length>=50)return;const r=rows.rows[0].cloneNode(true);r.querySelectorAll('input').forEach(input=>input.value=input.name.endsWith('[unit]')?'UN':input.name.endsWith('[quantity]')?'1.000':'');rows.appendChild(r);names();});rows.addEventListener('click',event=>{if(event.target.classList.contains('purchase-remove-line')&&rows.rows.length>1){event.target.closest('tr').remove();names();}});})();</script>
